"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["6012"],{14079(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>d,frontMatter:()=>r,contentTitle:()=>a,toc:()=>l,assets:()=>h});var o=JSON.parse('{"id":"qiangguo/educatetheleft","title":"","description":"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/educatetheleft.md","sourceDirName":"qiangguo","slug":"/qiangguo/educatetheleft","permalink":"/en/qiangguo/educatetheleft","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"educatetheleft","title":"","hide_table_of_contents":true,"sidebar_label":"Seeing \\"French Chef\\" Is Still Humble, Let\'s Continue Educating the Leftists"},"sidebar":"qiangguoSidebar","previous":{"title":"\u4E3A\u4EC0\u4E48\u4E00\u4E2A\u9519\u6F0F\u767E\u51FA\u7684\u5E16\u5B50\u7ADF\u7136\u5F97\u5230\u4E00\u81F4\u7684\u559D\u5F69\uFF1F\uFF08\u6CE8\uFF1A\u5173\u4E8E\u7F57\u7D20\u6096\u8BBA\u548C\u54E5\u5FB7\u5C14\u5B9A\u7406\uFF09","permalink":"/en/qiangguo/postofflaws"},"next":{"title":"Seeing \\"French Chef\\" Is Still Humble, Let\'s Educate the Leftists One More Time!","permalink":"/en/qiangguo/educatetheleftmore"}}'),i=n(74848),s=n(28453);let r={id:"educatetheleft",title:"",hide_table_of_contents:!0,sidebar_label:'Seeing "French Chef" Is Still Humble, Let\'s Continue Educating the Leftists'},a='Seeing That "French Grand Chef" Remains Relatively Humble, Let Us Continue Educating the Left!',h={},l=[];function u(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"seeing-that-french-grand-chef-remains-relatively-humble-let-us-continue-educating-the-left",children:'Seeing That "French Grand Chef" Remains Relatively Humble, Let Us Continue Educating the Left!'})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:'The reason for continuing to educate the left is that "French Grand Chef" remains relatively humble. Although this person still does not fully understand the proof, at least their attitude is one of discussing the problem. Among all leftists, at least so far, despite still having confused areas, they are the most clear-headed -- not like certain people who can only deny everything, or certain others who haven\'t even figured out the conditions under which the diagonal method applies and still go around embarrassing themselves.'}),"\n",(0,i.jsx)(t.p,{children:'Since this is a proof by contradiction, all argumentation proceeds from the hypothesis that "all human thoughts can be stored in binary computers," then derives a contradiction, thereby proving the absurdity of this premise. Since we are talking about storing things in a computer, this means these binary numbers can be lined up in order. Whether they are finite or not does not affect the argument, though in practice, these numbers are indeed finite. From your post, I can see you understand this point. Everyone else must understand this first -- otherwise there is no need to read further.'}),"\n",(0,i.jsx)(t.p,{children:'Second, since "all human thoughts can be stored in binary computers," every thought within all human thoughts is encoded into a corresponding binary number. These numbers form a set A. In other words, all binary numbers are divided into two categories: those belonging to set A, and those not belonging to set A. We call those in set A "A-numbers" and those not in set A "B-numbers." You should be able to understand this.'}),"\n",(0,i.jsx)(t.p,{children:"Now, let us examine those binary numbers not belonging to set A -- namely, the B-numbers. These numbers, under this encoding, do not correspond to any human thought; otherwise, by the definition above, they would belong to set A. This point you should also be able to understand, though you might get confused."}),"\n",(0,i.jsx)(t.p,{children:'Good. Now apply the diagonal method to set A. The binary number corresponding to the diagonal will certainly not belong to set A -- that is, this binary number must be a B-number. However, this binary number corresponds to the following thought: "its Nth digit differs from the Nth digit of the Nth binary number in set A." In other words, this binary number should be an A-number. I trust that after careful study, you will be able to understand this.'}),"\n",(0,i.jsx)(t.p,{children:'From the above analysis, we can find a binary number that is both an A-number and a B-number -- meaning it both belongs to and does not belong to set A. This contradicts the definition of a set. Why does this contradiction arise? Because the initial hypothesis -- "all human thoughts can be stored in binary computers" -- is wrong. By proof by contradiction, we know: "Not all human thoughts can be stored in binary computers." Here, I trust that as long as you are not someone who lets their backside dictate their brain, you should understand clearly.'}),"\n",(0,i.jsx)(t.p,{children:"In short, when the left makes errors, just admit them. You can always gloss it over with a \"victory and defeat are the common lot of warriors.\" There are plenty of knowledgeable people nowadays. If you insist on being stubborn as a duck's beak on such a simple issue, you will only embarrass yourselves before the majority of onlookers -- and that can't be good for your recruitment of lackeys either!"})]})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>a});var o=n(96540);let i={},s=o.createContext(i);function r(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);